func (d *Downloader) getProtocolConfig(name string, v any) bool {
	cfg, err := d.GetConfig()
	if err != nil {
		return false
	}
	if cfg.ProtocolConfig == nil || cfg.ProtocolConfig[name] == nil {
		return false
	}
	if err := util.MapToStruct(cfg.ProtocolConfig[name], v); err != nil {
		d.Logger.Warn().Err(err).Msgf("get protocol config failed")
		return false
	}
	return true
}

// wait task done
func (d *Downloader) watch(task *Task) {
	if _, loaded := d.watchedTasks.LoadOrStore(task.ID, true); loaded {
		return
	}
	defer func() {
		d.watchedTasks.Delete(task.ID)
	}()

	// wait task upload done
	if task.Uploading {
		if uploader, ok := task.fetcher.(fetcher.Uploader); ok {
			go func() {
				err := uploader.WaitUpload()
				if err != nil {
					d.Logger.Warn().Err(err).Msgf("task wait upload failed, task id: %s", task.ID)
				}

				// Check if the task is deleted
				if d.GetTask(task.ID) != nil {
					task.Uploading = false
					d.storage.Put(bucketTask, task.ID, task.clone())
				}
			}()
		}
	}

	if d.taskStatus(task) == base.DownloadStatusDone {
		return
	}

	for {
		err := task.fetcher.Wait()
		if err != nil {
			status := d.taskStatus(task)
			if status == base.DownloadStatusPause || status == base.DownloadStatusWait {
				return
			}
			var sourceErr error
			if d.blob != nil && task.Meta != nil && task.Meta.Req != nil {
				sourceErr = d.blob.SourceError(task.Meta.Req.URL)
			}
			if sourceErr != nil {
				d.doOnBlobSourceError(task, sourceErr)
			} else {
				d.doOnError(task, err)
			}
			if d.taskStatus(task) == base.DownloadStatusRunning {
				continue
			}
			return
		}

		// When delete a not resolved task, need check if the task resource is nil
		if task.Meta.Res == nil || d.GetTask(task.ID) == nil {
			return
		}
		if d.blob != nil && task.Meta.Req != nil {
			if err := d.blob.SourceError(task.Meta.Req.URL); err != nil {
				d.doOnBlobSourceError(task, err)
				if d.taskStatus(task) == base.DownloadStatusRunning {
					continue
				}
				return
			}
		}

		if !d.markTaskDone(task) {
			return
		}
		if err := d.captureTaskStats(task, false, true); err != nil {
			d.Logger.Error().Stack().Err(err).Msgf("persist completed task stats failed, task id: %s", task.ID)
		}
		task.statusLock.Lock()
		snapshot := task.clone()
		task.statusLock.Unlock()
		d.storage.Put(bucketTask, task.ID, snapshot)
		d.emit(EventKeyDone, task)
		d.emit(EventKeyFinally, task, err)
		d.notifyRunning()
		d.releaseBlobTask(task)
		d.triggerOnDone(task)
		d.triggerWebhooks(WebhookEventDownloadDone, task, nil)
		d.triggerScripts(ScriptEventDownloadDone, task, nil)

		if e := postDownloadExtra(task.Meta); e != nil {
			downloadFilePath := task.Meta.SingleFilepath()

			cfg, _ := d.GetConfig()

			// Determine if auto-torrent is enabled (use global config if not explicitly set)
			autoTorrentEnabled := false
			if e.AutoTorrent != nil {
				autoTorrentEnabled = *e.AutoTorrent
			} else if cfg != nil && cfg.AutoTorrent != nil {
				autoTorrentEnabled = cfg.AutoTorrent.Enable
			}

			if autoTorrentEnabled && strings.HasSuffix(downloadFilePath, ".torrent") {
				// Determine if should delete torrent file after creating BT task
				shouldDelete := false
				if e.DeleteTorrentAfterDownload != nil {
					shouldDelete = *e.DeleteTorrentAfterDownload
				} else if cfg != nil && cfg.AutoTorrent != nil {
					shouldDelete = cfg.AutoTorrent.DeleteAfterDownload
				}

				go func() {
					_, err2 := d.CreateDirect(
						&base.Request{
							URL: downloadFilePath,
						},
						&base.Options{
							Path:        task.Meta.Opts.Path,
							SelectFiles: make([]int, 0),
						})
					if err2 != nil {
						d.Logger.Error().Err(err2).Msgf("auto create torrent task failed, task id: %s", task.ID)
						return
					}

					if shouldDelete {
						d.Delete(&TaskFilter{IDs: []string{task.ID}}, true)
					}
				}()
			}

			// Determine if auto-extract is enabled (use global config if not explicitly set)
			autoExtractEnabled := false
			if e.AutoExtract != nil {
				autoExtractEnabled = *e.AutoExtract
			} else if cfg != nil && cfg.Archive != nil {
				autoExtractEnabled = cfg.Archive.AutoExtract
			}

			// Auto-extract archive files using the extraction queue
			// This ensures only one extraction runs at a time to prevent resource exhaustion
			if autoExtractEnabled && isArchiveFile(downloadFilePath) {
				d.enqueueExtraction(task, downloadFilePath, e)
			}
		}
		return
	}
}

// postDownloadExtra returns the auto-torrent and auto-extract options of a
// finished single-file task, in the HTTP options shape the extraction code
// takes. FTP options carry the same fields. An FTP folder has no single file
// to act on, so it gets nil, as does any other protocol.
func postDownloadExtra(meta *fetcher.FetcherMeta) *http.OptsExtra {
	if meta == nil || meta.Opts == nil {
		return nil
	}
	switch e := meta.Opts.Extra.(type) {
	case *http.OptsExtra:
		return e
	case *ftp.OptsExtra:
		if meta.Res == nil || meta.Res.Name != "" || len(meta.Res.Files) != 1 {
			return nil
		}
		return &http.OptsExtra{
			Connections:                e.Connections,
			AutoTorrent:                e.AutoTorrent,
			DeleteTorrentAfterDownload: e.DeleteTorrentAfterDownload,
			AutoExtract:                e.AutoExtract,
			ArchivePassword:            e.ArchivePassword,
			DeleteAfterExtract:         e.DeleteAfterExtract,
		}
	}
	return nil
}

func (d *Downloader) doOnError(task *Task, err error) {
	d.handleOnError(task, err, false)
}

func (d *Downloader) doOnBlobSourceError(task *Task, err error) {
	d.handleOnError(task, err, true)
}

func (d *Downloader) handleOnError(task *Task, err error, resetFetcher bool) {
	if task == nil || task.lock == nil {
		return
	}
	task.lock.Lock()
	if !d.markTaskError(task) {
		task.lock.Unlock()
		return
	}
	d.Logger.Warn().Err(err).Msgf("task download failed, task id: %s", task.ID)
	oldURL := ""
	if task.Meta != nil && task.Meta.Req != nil {
		oldURL = task.Meta.Req.URL
	}

package download

import (
	"encoding/json"
	"sync"
	"time"

	"github.com/GopeedLab/gopeed/internal/controller"
	"github.com/GopeedLab/gopeed/internal/fetcher"
	"github.com/GopeedLab/gopeed/internal/production"
	"github.com/GopeedLab/gopeed/internal/protocol/bt"
	"github.com/GopeedLab/gopeed/internal/protocol/ed2k"
	"github.com/GopeedLab/gopeed/internal/protocol/ftp"
	"github.com/GopeedLab/gopeed/internal/protocol/hls"
	"github.com/GopeedLab/gopeed/internal/protocol/http"
	"github.com/GopeedLab/gopeed/pkg/base"
	enginewebview "github.com/GopeedLab/gopeed/pkg/download/engine/webview"
	"github.com/GopeedLab/gopeed/pkg/util"
	gonanoid "github.com/matoous/go-nanoid/v2"
)

type ResolveResult struct {
	ID  string         `json:"id"`
	Res *base.Resource `json:"res"`
	// SuggestedDownloadDir is the category directory the created task would be
	// routed to. It is only set when auto categorize is enabled, the resource is
	// a single file, a category matches and its directory passes the white list
	// check. It is a hint for the ui, the create call decides the final path.
	SuggestedDownloadDir string `json:"suggestedDownloadDir,omitempty"`
}

// Task represents a download unit.
// Options flow path:
// REST Request (model.CreateTask/ResolveTask) -> pkg/download Downloader -> Task.Meta.Opts (base.Options) -> Fetcher.Resolve/Start (e.g. internal/protocol/http/fetcher.go)
type Task struct {
	ID        string               `json:"id"`
	Protocol  string               `json:"protocol"`
	Meta      *fetcher.FetcherMeta `json:"meta"`
	Status    base.Status          `json:"status"`
	Uploading bool                 `json:"uploading"`
	Progress  *Progress            `json:"progress"`
	CreatedAt time.Time            `json:"createdAt"`
	UpdatedAt time.Time            `json:"updatedAt"`
	// DoneAt is the time when the task completed; nil if it has never
	// finished. A done task never leaves the done state, so the value is
	// written once and kept.
	DoneAt *time.Time `json:"doneAt"`
	// NeedsPreparation marks a task that has not run its first preparation
	// yet. The preparation decides the download directory of the task and
	// resolves the duplicate name in it. It runs once, after the resource is
	// resolved, and the flag is cleared afterwards, so a queued, paused or
	// retried task is still prepared while a prepared task is never
	// classified or renamed again. A task stored before this flag existed
	// does not have it and keeps its directory and name.
	NeedsPreparation bool `json:"needsPreparation,omitempty"`

	producer         production.Source
	producerReceived int64

	fetcherManager fetcher.FetcherManager
	fetcher        fetcher.Fetcher
	timer          *util.Timer
	statusLock     *sync.Mutex
	lock           *sync.Mutex
	statsLock      *sync.Mutex
	statsLoaded    bool
	stats          *fetcher.Stats
	statsSnapshot  json.RawMessage
	blobRefLock    *sync.Mutex
	blobURL        string
	runGeneration  uint64
	speedArr       []int64
	uploadSpeedArr []int64
}

// TaskRuntimeStatus is the lightweight, frequently refreshed view of a task.
// It intentionally excludes request, resource and option metadata returned by
// Task so detail pages can poll progress without repeatedly transferring the
// full task object.
type TaskRuntimeStatus struct {
	Status          base.Status         `json:"status"`
	Used            int64               `json:"used"`
	Speed           int64               `json:"speed"`
	Downloaded      int64               `json:"downloaded"`
	Total           int64               `json:"total"`
	UploadSpeed     int64               `json:"uploadSpeed"`
	Uploaded        int64               `json:"uploaded"`
	ExtractStatus   ExtractStatus       `json:"extractStatus"`
	ExtractProgress int                 `json:"extractProgress"`
	Files           []FileRuntimeStatus `json:"files"`
}

// FileRuntimeStatus maps one value returned by fetcher.Progress to its
// original resource index. Fetchers return progress in SelectFiles order.
type FileRuntimeStatus struct {
	Index      int   `json:"index"`
	Size       int64 `json:"size"`
	Downloaded int64 `json:"downloaded"`
}

func NewTask() *Task {
	id, err := gonanoid.New()
	if err != nil {
		panic(err)
	}
	return &Task{
		ID:        id,
		Status:    base.DownloadStatusReady,
		CreatedAt: time.Now(),
		UpdatedAt: time.Now(),
	}
}

// Name returns the display name of the task.
func (t *Task) Name() string {
	// Custom name first
	if t.Meta.Opts.Name != "" {
		return t.Meta.Opts.Name
	}

	// Task is not resolved, parse the name from the URL
	if t.Meta.Res == nil {
		fallbackName := "unknown"
		if t.fetcherManager == nil {
			return fallbackName
		}
		parseName := t.fetcherManager.ParseName(t.Meta.Req.URL)
		if parseName == "" {
			return fallbackName
		}
		return parseName
	}

	// Task is a folder
	if t.Meta.Res.Name != "" {
		return t.Meta.Res.Name
	}

	// Get the name of the first file
	return t.Meta.Res.Files[0].Name
}

func (t *Task) MarshalJSON() ([]byte, error) {
	type rawTaskType Task
	jsonTask := struct {
		*rawTaskType
		Name string `json:"name"`
	}{
		(*rawTaskType)(t),
		t.Name(),
	}
	return json.Marshal(jsonTask)
}

func (t *Task) updateStatus(status base.Status) {
	t.UpdatedAt = time.Now()
	t.Status = status
	// A done task never leaves the done state, so there is no branch to clear
	// DoneAt on other transitions.
	if status == base.DownloadStatusDone {
		doneAt := time.Now()
		t.DoneAt = &doneAt
	}
}

func (t *Task) clone() *Task {
	return util.DeepClone(t)
}

func (t *Task) updateSpeed(downloaded int64, usedTime float64) int64 {
	return calcSpeed(&t.speedArr, downloaded, usedTime)
}

func (t *Task) updateUploadSpeed(downloaded int64, usedTime float64) int64 {
	return calcSpeed(&t.uploadSpeedArr, downloaded, usedTime)
}

func calcSpeed(speedArr *[]int64, downloaded int64, usedTime float64) int64 {
	if usedTime <= 0 {
		return 0
	}
	if downloaded < 0 {
		*speedArr = (*speedArr)[:0]
		return 0
	}

	*speedArr = append(*speedArr, downloaded)
	// Record last 5 seconds of download speed to calculate the average speed
	if len(*speedArr) > int(5.0/usedTime) {
		*speedArr = (*speedArr)[1:]
	}

	var total int64
	for _, v := range *speedArr {
		total += v
	}

	return int64(float64(total) / float64(len(*speedArr)) / usedTime)
}

type TaskFilter struct {
	IDs         []string
	Statuses    []base.Status
	NotStatuses []base.Status
}

func (f *TaskFilter) IsEmpty() bool {
	return len(f.IDs) == 0 && len(f.Statuses) == 0 && len(f.NotStatuses) == 0
}

type DownloaderConfig struct {
	Controller    *controller.Controller
	FetchManagers []fetcher.FetcherManager

	RefreshInterval   int // RefreshInterval time duration to refresh task progress(ms)
	Storage           Storage
	StorageDir        string
	TempDir           string
	WhiteDownloadDirs []string
	WebViewProvider   enginewebview.Provider

	ProductionMode bool

	*base.DownloaderStoreConfig
}

func (cfg *DownloaderConfig) Init() *DownloaderConfig {
	if cfg.Controller == nil {
		cfg.Controller = controller.NewController()
	}
	if len(cfg.FetchManagers) == 0 {
		cfg.FetchManagers = []fetcher.FetcherManager{
			// FTP matches by URL scheme only. It comes before the managers that
			// match by file extension, so ftp://host/x.torrent or x.m3u8 is
			// downloaded as a file over FTP.
			new(ftp.FetcherManager),
			new(hls.FetcherManager),
			new(http.FetcherManager),
			new(bt.FetcherManager),
			new(ed2k.FetcherManager),
