func (d *Downloader) releaseBlobTaskURL(task *Task, raw string) {
	if d.blob == nil || task == nil || raw == "" {
		return
	}
	if task.blobRefLock == nil {
		task.blobRefLock = &sync.Mutex{}
	}
	task.blobRefLock.Lock()
	claimed := task.blobURL == raw
	if claimed {
		task.blobURL = ""
